  "d": "Carbamazepine",
  "ans": "A",
  "e": "Senile plaques in Alzheimer disease contain amyloid-beta; extracellular aggregates of amyloid-beta peptide cleaved from amyloid precursor protein form the senile plaque core surrounded by dystrophic neurites.<br><br>Tau neurofibrillary tangles are intracellular paired helical filaments of hyperphosphorylated tau protein. APP, PSEN1, and PSEN2 mutations cause early-onset familial Alzheimer disease. APOE epsilon-4 is the principal late-onset genetic risk factor identified.<br><br>Tau protein only (option A) describes neurofibrillary tangles not plaques; alpha-synuclein (option C) is in Parkinson Lewy bodies; prion protein (option D) is in Creutzfeldt-Jakob disease, none being the plaque amyloid component.<br><br><em>(First Aid for USMLE Step 1)</em>"
