  "e": "Tetrabenazine helps Huntington chorea; this VMAT2 inhibitor depletes presynaptic dopamine, reducing chorea severity in symptomatic Huntington disease patients with disabling involuntary movements.<br><br>Side effects include depression, parkinsonism, akathisia, and sedation. Deutetrabenazine and valbenazine are newer VMAT2 inhibitors with improved tolerability. Counselling for depression and suicide risk is essential before initiating these dopamine-depleting agents in Huntington disease patients.<br><br>Levodopa (option A) treats Parkinson disease; donepezil (option C) treats Alzheimer disease; baclofen (option D) treats spasticity, none being effective for the chorea of Huntington disease specifically.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
