  "e": "Korsakoff syndrome psychosis is anterograde amnesia with confabulation; chronic untreated thiamine deficiency producing irreversible mammillary body and thalamic damage causes profound recent memory loss with characteristic confabulation.<br><br>Wernicke encephalopathy progresses to Korsakoff syndrome in 80 percent of untreated cases. Confabulation, executive dysfunction, and apathy accompany memory loss. Long-term thiamine supplementation and abstinence are foundational management; cognitive rehabilitation provides limited benefit clinically.<br><br>Anxiety only (option B) is non-specific; tremor (option C) is movement disorder; depression only (option D) is mood disorder, none being the principal anterograde amnesia and confabulation of Korsakoff syndrome.<br><br><em>(First Aid for USMLE Step 1)</em>"
