  "e": "Multiple sclerosis pathology shows demyelinating plaques; immune-mediated destruction of CNS myelin produces multifocal plaques predominantly in periventricular white matter, optic nerves, brainstem, and spinal cord.<br><br>Pathology features inflammatory infiltrates with macrophages, lymphocytes, and oligodendrocyte loss. Acute lesions show active demyelination; chronic lesions show gliosis. McDonald criteria require dissemination in space and time on imaging or clinically.<br><br>Amyloid plaques (option A) are in Alzheimer disease; Lewy bodies (option B) in Parkinson disease; neurofibrillary tangles (option C) in Alzheimer disease, none being the multiple sclerosis demyelinating plaque pathology specifically.<br><br><em>(First Aid for USMLE Step 1)</em>"
