  "e": "Most common subtype of multiple sclerosis is relapsing-remitting MS; episodes of neurological dysfunction followed by complete or partial recovery characterise this initial pattern in 85 percent of patients.<br><br>Most patients develop secondary progressive MS over 15-20 years. Primary progressive MS shows steady deterioration without relapses from onset in 10-15 percent. Treatment includes disease-modifying therapies tailored to subtype and disease activity in clinical practice.<br><br>Primary progressive (option B) shows steady decline; secondary progressive (option C) follows initial RRMS phase; benign MS (option D) is retrospective designation, none being the most common initial subtype of multiple sclerosis.<br><br><em>(First Aid for USMLE Step 1)</em>"
