  "e": "Lhermitte sign in MS is electric-shock sensation down spine on neck flexion; cervical spinal cord demyelination produces this characteristic paresthesia from mechanical stimulation of demyelinated dorsal columns.<br><br>Lhermitte sign also occurs in cervical spondylosis, vitamin B12 deficiency, and radiation myelopathy. Uhthoff phenomenon describes transient neurological worsening with heat or exercise, classic in MS optic neuritis. Both are useful diagnostic clues clinically.<br><br>Headache after exertion (option A) is non-specific; tongue tingling (option C) is unusual; foot pain on cold (option D) is non-specific, none being the Lhermitte cervical-flexion electric-shock sign of MS.<br><br><em>(First Aid for USMLE Step 1)</em>"
