  "e": "Mini-Mental State Examination is the most useful test for screening dementia; brief 30-point bedside cognitive assessment evaluates orientation, memory, attention, language, and visuospatial function in clinical practice.<br><br>Score below 24 suggests cognitive impairment. Education and cultural background influence performance. Montreal Cognitive Assessment is alternative with better detection of mild cognitive impairment. Comprehensive neuropsychological testing is needed when bedside testing yields equivocal results clinically.<br><br>CT brain (option A) is structural imaging not cognitive; lumbar puncture (option B) is invasive; EEG (option D) detects encephalopathy or seizures, none being the principal bedside dementia screening tool.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
