  "e": "Vascular dementia is described as stepwise cognitive decline; sequential cerebrovascular events produce abrupt declines with intervening stable periods, contrasting with the gradual progression of Alzheimer disease.<br><br>Risk factors include hypertension, diabetes, atrial fibrillation, and previous stroke. Imaging shows multiple infarcts, white matter disease, or strategic single infarcts. Aggressive vascular risk factor management slows progression. Cholinesterase inhibitors provide modest benefit in some patients.<br><br>Gradually progressive (option A) suggests Alzheimer disease; rapidly progressive (option B) suggests prion disease; fluctuating (option D) suggests Lewy body dementia, none matching the stepwise vascular dementia decline characteristically observed.<br><br><em>(First Aid for USMLE Step 1)</em>"
