  "b": "Stroke",
  "c": "Delirium tremens",
  "d": "Migraine",
  "ans": "C",
  "e": "Multiple sclerosis disease-modifying drug includes interferon beta; injectable disease-modifying therapy reduces relapse rate by approximately 30 percent and slows disability progression in relapsing-remitting MS.<br><br>Other established therapies include glatiramer acetate (injectable), oral agents (dimethyl fumarate, teriflunomide, fingolimod, cladribine), and high-efficacy infusions (natalizumab, ocrelizumab, ofatumumab, alemtuzumab). Treatment selection considers efficacy, safety, and patient preferences in shared decision-making.<br><br>Levodopa (option A) treats Parkinson disease; donepezil (option C) treats Alzheimer disease; phenytoin (option D) treats epilepsy, none being effective disease-modifying multiple sclerosis treatment.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
