  "c": "Deafness",
  "d": "Falls",
  "ans": "D",
  "e": "Postural instability in Parkinson disease leads to falls; impaired postural reflexes from progressive disease produce backward falls (retropulsion) on examination, particularly during pull test.<br><br>Postural instability is a late motor feature, typically appearing 5-10 years after onset of cardinal motor symptoms. Falls cause significant morbidity including hip fractures and head injury. Physical therapy, gait training, and home modifications reduce fall frequency in clinical practice.<br><br>Tremor (option A) is early feature without falls; dementia (option B) develops later but does not directly cause falls; rigidity (option C) is early feature, none being principal cause of falls in Parkinson.<br><br><em>(First Aid for USMLE Step 1)</em>"
