  "e": "Dementia in Lewy body disease shows fluctuating cognition; cognitive performance varies markedly over hours to days alongside visual hallucinations and parkinsonism in this synucleinopathy.<br><br>Core features include fluctuating cognition, visual hallucinations, and parkinsonism. Supportive features include REM sleep behaviour disorder and severe neuroleptic sensitivity. Cholinesterase inhibitors (rivastigmine) help cognitive and behavioural symptoms more effectively than in other dementias clinically.<br><br>Steady (option A) describes Alzheimer disease; stepwise (option C) describes vascular dementia; rapidly progressive (option D) suggests prion disease, none being the fluctuating Lewy body dementia cognitive pattern characteristically.<br><br><em>(First Aid for USMLE Step 1)</em>"
