  "e": "Rivastigmine is the drug of choice in Lewy body dementia; cholinesterase inhibition provides greater cognitive and behavioural benefit in Lewy body disease than in Alzheimer disease typically.<br><br>Visual hallucinations and behavioural symptoms also respond. Cholinergic deficit in Lewy body disease is severe, explaining favourable response. Antipsychotics are avoided due to severe neuroleptic sensitivity; quetiapine is used cautiously when essential for behavioural management in clinical practice.<br><br>Levodopa (option B) treats parkinsonism but worsens hallucinations; valproate (option C) treats seizures and bipolar disorder; haloperidol (option D) is contraindicated due to neuroleptic sensitivity, none being first-line.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
