  "e": "Subacute combined degeneration is due to vitamin B12 deficiency; demyelination of dorsal columns and lateral corticospinal tracts produces ascending paraesthesia, sensory ataxia, and pyramidal signs.<br><br>Megaloblastic anaemia, glossitis, and cognitive change accompany the neurological picture. Autoimmune pernicious anaemia, gastric atrophy, ileal disease, and dietary deficiency cause B12 deficiency. Parenteral B12 replacement reverses neurological deficits if started early before irreversible damage develops.<br><br>Vitamin B1 (option A) deficiency causes Wernicke encephalopathy; vitamin C (option C) deficiency causes scurvy; vitamin K (option D) deficiency causes coagulopathy, none being the subacute combined degeneration pathology of B12 deficiency.<br><br><em>(First Aid for USMLE Step 1)</em>"
