  "e": "Multiple sclerosis is associated with EBV exposure; recent epidemiological evidence supports Epstein-Barr virus infection as a major causal risk factor for multiple sclerosis development.<br><br>Other risk factors include vitamin D deficiency, smoking, obesity in adolescence, and HLA-DRB1*15:01 genotype. Geographic prevalence increases with latitude. Female predominance is approximately 3:1. EBV-targeted therapies are emerging as potential disease-modifying approaches in trials.<br><br>Hepatitis B (option A), HIV (option C), and HSV (option D) are not the principal viral risk factors for multiple sclerosis development, leaving Epstein-Barr virus as the established causal viral exposure in MS pathogenesis.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
