  "a": "Brain tumor",
  "b": "Migraine",
  "c": "Meningitis",
  "d": "Encephalitis",
  "ans": "C",
  "e": "Bacterial meningitis is the most likely diagnosis; fever, headache, neck stiffness, and photophobia in young patient with rapid evolution suggest bacterial meningitis requiring urgent investigation.<br><br>Streptococcus pneumoniae and Neisseria meningitidis are the principal pathogens in adults. Empirical ceftriaxone and vancomycin (with dexamethasone) should not be delayed for lumbar puncture. CSF analysis confirms diagnosis with elevated polymorphs, low glucose, raised protein.<br><br>Migraine (option A) lacks fever and meningism; viral encephalitis (option B) features altered consciousness and seizures; subarachnoid haemorrhage (option D) is sudden thunderclap without fever, distinct from acute bacterial meningitis.<br><br><em>(First Aid for USMLE Step 1)</em>"
