  "d": "Listeria monocytogenes",
  "ans": "B",
  "e": "Empirical treatment for bacterial meningitis is intravenous third-generation cephalosporin; ceftriaxone or cefotaxime covers the most common adult pathogens including pneumococcus and meningococcus.<br><br>Vancomycin is added to cover penicillin-resistant pneumococcus pending sensitivities. Ampicillin is added for Listeria coverage in patients over 50 or immunocompromised. Dexamethasone administered before or with antibiotics reduces mortality and neurological sequelae in pneumococcal meningitis specifically.<br><br>Oral amoxicillin (option A) is inadequate for severe meningitis; oral azithromycin (option B) is for atypical pneumonia; oral fluconazole (option D) treats fungal infection, none being adequate empirical bacterial meningitis treatment.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
