  "ans": "A",
  "e": "Dexamethasone in bacterial meningitis reduces mortality and hearing loss; corticosteroid administration before or with antibiotics decreases inflammatory response and prevents auditory damage primarily in pneumococcal meningitis.<br><br>Standard regimen is 10 mg intravenously every 6 hours for 4 days. Benefit is greatest in pneumococcal meningitis. Continued only if pneumococcus confirmed; discontinued in other organisms. Mechanism involves reduced cytokine-mediated cochlear and neuronal damage during bacterial lysis.<br><br>Increase intracranial pressure (option B), reduce CSF flow (option C), and increase brain oedema (option D) describe negative effects, not the established benefits of dexamethasone in pneumococcal meningitis treatment regimens.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
