  "e": "Bacterial meningitis CSF shows neutrophilic pleocytosis with low glucose; cell count exceeds 1000/mm3 with neutrophil predominance, glucose under 40 mg/dL, and protein over 100 mg/dL typically.<br><br>Gram stain identifies organism in 60-90 percent of cases. CSF lactate over 35 mg/dL supports bacterial aetiology. CSF cultures provide definitive identification. PCR panels increasingly used for rapid pathogen identification including viral, bacterial, and fungal organisms in CSF samples.<br><br>Lymphocytic with normal glucose (option B) suggests viral meningitis; eosinophilic (option C) suggests parasitic infection; normal CSF (option D) excludes meningitis, none matching the bacterial neutrophilic low-glucose pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
