  "ans": "A",
  "e": "Lumbar puncture in suspected meningitis shows elevated protein and low glucose in bacterial infection; bacterial consumption of glucose and exudate of inflammatory protein produce these characteristic findings.<br><br>Cell count exceeds 1000/mm3 with neutrophil predominance. Gram stain identifies organism in 60-90 percent. Bacterial cultures provide definitive identification. Brain imaging precedes lumbar puncture only when raised intracranial pressure or focal neurological signs are suspected clinically.<br><br>Normal protein with raised glucose (option B) is non-physiological; raised glucose only (option C) does not occur; bloody CSF only (option D) suggests subarachnoid haemorrhage, none being the bacterial meningitis CSF pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
