  "d": "High",
  "ans": "D",
  "e": "Pneumococcal meningitis vaccine prevention is by polyvalent pneumococcal vaccine; PCV13 and PPSV23 vaccines target multiple capsular polysaccharide serotypes responsible for invasive pneumococcal disease including meningitis.<br><br>Routine childhood vaccination, vaccination of adults over 65, and vaccination of high-risk patients (asplenia, immunocompromise, chronic disease) substantially reduce incidence. Herd immunity provides additional community protection against vaccine-targeted serotypes in unvaccinated individuals.<br><br>Hepatitis vaccine (option A) prevents hepatitis B; rabies vaccine (option B) prevents rabies; influenza vaccine (option D) prevents seasonal influenza, none being the principal pneumococcal meningitis vaccination strategy.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
