  "e": "Tuberculous meningitis predominant CSF cell type is lymphocytes; chronic mycobacterial meningitis produces lymphocytic pleocytosis with elevated protein, low glucose, and basal meningeal involvement.<br><br>CSF acid-fast staining and culture have low sensitivity. PCR for Mycobacterium tuberculosis improves rapid diagnosis. Treatment includes four-drug antitubercular therapy with adjunctive corticosteroids. Hydrocephalus, cranial nerve palsies, and tuberculomas complicate disease in many patients clinically.<br><br>Neutrophils (option A) suggest bacterial meningitis; eosinophils (option C) suggest parasitic infection; basophils (option D) are not a CSF cell type, none matching the tuberculous lymphocytic predominance.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
