  "e": "Ampicillin is added in elderly meningitis for Listeria coverage; Listeria monocytogenes is a cause of meningitis in patients over 50 years old, immunocompromised, and pregnant patients.<br><br>Listeria is intrinsically resistant to cephalosporins, requiring ampicillin (or trimethoprim-sulfamethoxazole in penicillin-allergic patients). Empirical regimen for elderly meningitis combines third-generation cephalosporin, vancomycin, ampicillin, and dexamethasone in pneumococcal cases until cultures direct therapy.<br><br>Vancomycin (option B) covers penicillin-resistant pneumococcus not Listeria; ceftriaxone (option C) lacks Listeria activity; rifampicin (option D) is for tuberculosis primarily, none being Listeria-active for empirical elderly meningitis.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
