  "c": "Kill bacteria",
  "d": "Reduce inflammatory complications",
  "ans": "D",
  "e": "In meningococcaemia, intramuscular benzylpenicillin should be given immediately; pre-hospital antibiotic administration in suspected meningococcal infection saves lives by reducing bacterial load before specialist care.<br><br>Single intramuscular benzylpenicillin dose is given by general practitioners at first contact in primary care. Public health notification, contact tracing, and chemoprophylaxis (rifampicin, ciprofloxacin) follow hospital admission. Vaccination programs against serogroups B and C reduce community incidence substantially.<br><br>Rifampicin (option A) is for chemoprophylaxis of contacts; vancomycin (option C) is for hospital empirical therapy; ciprofloxacin (option D) is for chemoprophylaxis, none being first-line pre-hospital meningococcaemia treatment.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
