  "e": "Cryptococcal meningitis is associated with HIV; immunocompromised patients particularly with CD4 under 100 are at high risk of Cryptococcus neoformans infection of the meninges and brain parenchyma.<br><br>India ink staining shows encapsulated yeast in CSF. Cryptococcal antigen testing has high sensitivity and specificity. Treatment with amphotericin B and flucytosine for induction, followed by fluconazole consolidation and maintenance, controls infection. Antiretroviral therapy initiation requires careful timing.<br><br>Tuberculosis (option A) is also HIV-associated but bacterial; viral encephalitis (option C) is acute; bacterial meningitis (option D) is acute pyogenic, distinct from chronic fungal cryptococcal meningitis in immunocompromised hosts.<br><br><em>(First Aid for USMLE Step 1)</em>"
