  "c": "High neutrophils",
  "d": "Normal glucose",
  "ans": "D",
  "e": "Meningococcus is identified microbiologically as Gram-negative diplococci; this organism appears as kidney bean-shaped Gram-negative diplococci on Gram stain of CSF or blood culture.<br><br>Neisseria meningitidis colonises the nasopharynx in carriers. Invasive disease produces meningitis, meningococcaemia, and rarely pneumonia. Capsular polysaccharide vaccines prevent serogroups A, C, W, Y; protein vaccines target serogroup B identified in some adolescents.<br><br>Gram-positive cocci (option B) include staphylococci and streptococci; Gram-positive rods (option C) include Listeria; Gram-negative rods (option D) include Haemophilus, none being the diplococcal meningococcal Gram-negative pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
