  "c": "HSV encephalitis",
  "d": "Migraine",
  "ans": "C",
  "e": "Encephalitis is most commonly caused by herpes simplex virus; HSV-1 reactivation in temporal lobes produces the most common sporadic viral encephalitis in adults globally.<br><br>Patients present with fever, altered mental state, focal neurological deficits, and seizures. MRI shows temporal lobe oedema. CSF PCR for HSV is diagnostic. Acyclovir 10 mg/kg every 8 hours for 14-21 days reduces mortality from over 70 percent to 15-20 percent.<br><br>Mumps virus (option A) causes parotitis with rare encephalitis; coxsackievirus (option B) causes hand-foot-mouth disease; influenza virus (option D) rarely causes encephalitis, none being the principal sporadic viral encephalitis cause.<br><br><em>(First Aid for USMLE Step 1)</em>"
