  "e": "Acyclovir is the antiviral used in HSV encephalitis; intravenous acyclovir 10 mg/kg every 8 hours for 14-21 days reduces mortality from over 70 percent to 15-20 percent in HSV encephalitis.<br><br>Empirical treatment is started immediately when HSV encephalitis is suspected, before PCR confirmation. Side effects include nephrotoxicity (preventable by hydration) and neurotoxicity. Survivors often have significant neurological sequelae despite treatment, emphasising urgent recognition and treatment.<br><br>Ganciclovir (option B) treats CMV; ribavirin (option C) treats hepatitis C and respiratory syncytial virus; oseltamivir (option D) treats influenza, none being the principal HSV encephalitis treatment effective at high dose.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
