  "e": "Listeria monocytogenes is at risk in elderly and immunocompromised meningitis; this Gram-positive rod causes meningitis in patients over 50, immunocompromised, and pregnant women requiring ampicillin coverage.<br><br>Listeria is intrinsically resistant to cephalosporins, requiring ampicillin (or trimethoprim-sulfamethoxazole in penicillin-allergic patients). Empirical regimen for elderly meningitis includes third-generation cephalosporin, vancomycin, ampicillin, and dexamethasone in pneumococcal cases until cultures confirm.<br><br>Pneumococcus (option A) is the most common adult cause overall; meningococcus (option B) predominates in adolescents and young adults; Haemophilus (option D) has declined post-vaccination, distinct demographics from Listeria.<br><br><em>(First Aid for USMLE Step 1)</em>"
