  "e": "Rifampicin is the chemoprophylaxis for close contacts of meningococcal disease; oral rifampicin 600 mg twice daily for 2 days eliminates nasopharyngeal carriage and prevents secondary cases.<br><br>Alternatives include single-dose ciprofloxacin or ceftriaxone. Close contacts are defined as household members and others with prolonged close exposure within 7 days before disease onset. Public health notification triggers contact tracing and chemoprophylaxis distribution organised through public health authorities.<br><br>Penicillin (option A) does not eliminate carriage; vancomycin (option B) is for treatment; gentamicin (option D) is broad-spectrum aminoglycoside, none being the principal meningococcal contact chemoprophylaxis regimen administered after exposure.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
