  "c": "Acyclovir",
  "d": "Penicillin",
  "ans": "A",
  "e": "In meningococcaemia, the rapidly progressing rash that occurs is purpuric; non-blanching purpuric rash from disseminated intravascular coagulation accompanies fever and meningism in meningococcal sepsis.<br><br>Glass test demonstrates non-blanching purpura. Rapidly progressing rash signifies meningococcal sepsis with high mortality. Empirical ceftriaxone before lumbar puncture is essential. Adrenal haemorrhage causing Waterhouse-Friderichsen syndrome with shock can develop in severe meningococcal sepsis cases.<br><br>Pruritic (option A) suggests allergic; macular (option B) is non-specific; vesicular (option C) suggests viral exanthem, none matching the rapidly progressing purpuric meningococcal disseminated intravascular coagulation skin manifestation.<br><br><em>(First Aid for USMLE Step 1)</em>"
