  "e": "BCG vaccine prevents tuberculous meningitis to some extent in childhood; bacille Calmette-Guerin vaccine reduces severe forms of childhood tuberculosis including miliary disease and tuberculous meningitis.<br><br>BCG efficacy varies geographically; reasons remain unclear. Routine childhood BCG vaccination is policy in countries with high tuberculosis burden. Targeted use in low-burden countries focuses on healthcare workers and children of recent immigrants from endemic regions for protection.<br><br>HiB vaccine (option B) prevents Haemophilus influenzae type b meningitis; meningococcal vaccine (option C) prevents meningococcal disease; pneumococcal vaccine (option D) prevents pneumococcal meningitis, none being principal tuberculous prevention.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
