  "ans": "B",
  "e": "Kernig sign in meningitis indicates pain on knee extension when hip flexed; meningeal inflammation produces this resistance and pain reflecting irritation of nerve roots traversing inflamed meninges.<br><br>Brudzinski sign (involuntary hip-knee flexion on neck flexion) is related. Both signs have moderate sensitivity. Absence does not exclude meningitis. Definitive diagnosis requires CSF analysis. Differential includes lumbar disc disease and other causes of nerve root irritation requiring distinction clinically.<br><br>Loss of vision (option A) suggests optic neuropathy; chest pain (option C) is cardiac or pulmonary; abdominal rigidity (option D) suggests peritonitis, none being indicated by Kernig sign meningeal irritation specifically.<br><br><em>(First Aid for USMLE Step 1)</em>"
