  "e": "Neonatal meningitis common organism includes Group B streptococcus and Escherichia coli; these pathogens predominate in neonates aged 0-3 months alongside Listeria monocytogenes requiring different empirical coverage.<br><br>Group B streptococcus (Streptococcus agalactiae) is acquired during birth from maternal vaginal colonisation. Maternal intrapartum antibiotic prophylaxis reduces incidence. Empirical regimen for neonatal meningitis is ampicillin plus cefotaxime or aminoglycoside, providing broad coverage of these organisms while cultures pending.<br><br>Pneumococcus (option B) and Neisseria meningitidis (option C) are uncommon in neonates; Listeria (option D) is also a neonatal cause but less common than GBS, leaving GBS-E. coli as principal neonatal meningitis.<br><br><em>(First Aid for USMLE Step 1)</em>"
