  "e": "In meningitis CT before LP indicated for raised ICP signs; focal neurological deficits, seizures, papilloedema, altered consciousness, or immunocompromise warrant CT imaging before lumbar puncture.<br><br>Concern is herniation following lumbar puncture in raised intracranial pressure. CT cannot reliably exclude raised ICP but identifies mass effect or hydrocephalus. Empirical antibiotics should be given before imaging when indicated to avoid treatment delay in suspected bacterial meningitis cases.<br><br>Tachycardia alone (option B), mild fever (option C), and back pain (option D) are not contraindications to lumbar puncture, leaving raised intracranial pressure signs as the principal pre-LP imaging indication.<br><br><em>(First Aid for USMLE Step 1)</em>"
