  "e": "Common cause of recurrent meningitis is anatomical CSF leak; cribriform plate fracture, otologic CSF leak, or congenital anomaly allows recurrent bacterial entry from nasopharynx producing recurrent pyogenic meningitis.<br><br>Pneumococcus is the principal pathogen in CSF leak-related recurrent meningitis. CT cisternography or beta-2 transferrin testing of nasal discharge confirms CSF leak. Surgical repair prevents future episodes. Pneumococcal vaccination provides additional protection in patients with documented CSF leak.<br><br>Genetic disorders (option B) are rare causes; immune deficiency (option C) including complement deficiency causes recurrent meningococcal disease; viral infections (option D) are not recurrent typically, distinct from CSF-leak recurrent meningitis.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
