  "e": "Hib vaccine prevents Haemophilus meningitis; conjugate vaccine against Haemophilus influenzae type b polysaccharide capsule has dramatically reduced childhood meningitis incidence in vaccinated populations globally.<br><br>Routine childhood vaccination has eliminated Hib meningitis in countries with high coverage. Vaccine is given in infancy as part of routine immunisation schedules. Herd immunity provides additional community protection. Hib remains a cause of meningitis in unvaccinated children in some regions clinically.<br><br>Tuberculosis (option A) is prevented by BCG vaccine; pneumococcal disease (option B) by pneumococcal vaccines; meningococcal disease (option C) by meningococcal vaccines, none being the Hib-prevented disease specifically.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
