  "e": "Most dangerous complication of meningitis is herniation; raised intracranial pressure from inflammatory swelling, hydrocephalus, or abscess can precipitate brain herniation with rapid neurological deterioration and death.<br><br>Other complications include hydrocephalus, cranial nerve palsies (especially CN VI and VIII), seizures, focal infarction, subdural empyema, and chronic cognitive impairment. Hearing loss occurs in 5-30 percent of bacterial meningitis survivors. Long-term neurological sequelae affect significant proportion of survivors clinically.<br><br>Skin rash (option A) is non-life-threatening; cough (option C) is not meningitis complication; weight gain (option D) is not relevant, none being the principal life-threatening herniation complication of meningitis.<br><br><em>(First Aid for USMLE Step 1)</em>"
