  "e": "Acoustic neuroma main features include unilateral hearing loss; progressive unilateral sensorineural hearing loss, tinnitus, and balance disturbance comprise the principal clinical features at presentation.<br><br>Larger tumours produce facial nerve and trigeminal involvement, brainstem compression. MRI shows characteristic ice-cream cone appearance. Treatment options include observation for small asymptomatic tumours, stereotactic radiosurgery, and microsurgical resection depending on tumour size, hearing status, and patient preference clinically.<br><br>Bilateral hearing loss (option A) suggests NF2 or presbycusis; vertigo only (option C) is non-specific; facial pain only (option D) suggests trigeminal involvement, none being principal acoustic neuroma unilateral hearing loss feature.<br><br><em>(First Aid for USMLE Step 1)</em>"
