  "e": "Most common cause of papilloedema is raised intracranial pressure; transmitted pressure through optic nerve sheath produces bilateral optic disc swelling reflecting intracranial mass, hydrocephalus, idiopathic intracranial hypertension.<br><br>Fundoscopy shows blurred disc margins, hyperaemic disc, peripapillary haemorrhages, and obscured retinal vessels. Visual fields show enlarged blind spot. Differential diagnosis includes optic nerve disease, pseudopapilloedema, and benign anatomical variants requiring imaging and lumbar puncture for definitive evaluation.<br><br>Cataract (option A) is lens opacification; refractive errors (option C) are corrected with glasses; macular degeneration (option D) is age-related retinal disease, none being the principal raised intracranial pressure papilloedema cause.<br><br><em>(First Aid for USMLE Step 1)</em>"
