  "ans": "A",
  "e": "Most common adult brain tumour overall is meningioma; this benign extra-axial tumour arises from arachnoid cells, accounting for the largest proportion of primary intracranial tumours in adults.<br><br>Meningiomas typically present with headache, seizures, or focal deficits depending on location. Treatment includes observation for small asymptomatic lesions, surgical resection for symptomatic tumours, and radiotherapy for residual or recurrent disease. WHO grade I meningiomas have favourable prognosis after resection.<br><br>Glioblastoma (option B) is malignant most common; pituitary adenoma (option C) is sellar; oligodendroglioma (option D) is rarer, none being the principal overall adult primary brain tumour as benign meningioma.<br><br><em>(First Aid for USMLE Step 1)</em>"
