  "e": "Lumbar puncture in IIH shows elevated opening pressure; opening pressure exceeding 25 cm H2O with normal CSF composition (cell count, protein, glucose) is diagnostic of idiopathic intracranial hypertension.<br><br>Therapeutic lumbar puncture provides temporary relief but is not recommended for chronic management. Repeated procedures carry risk of post-LP headache and infection. Acetazolamide, weight loss, and surgical intervention provide more durable management of raised intracranial pressure in idiopathic intracranial hypertension clinically.<br><br>Bloody CSF (option A) suggests subarachnoid haemorrhage; low pressure (option C) is opposite of IIH; xanthochromia (option D) indicates blood breakdown, none matching the elevated opening pressure with normal composition pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
