  "c": "Median nerve",
  "d": "Axillary nerve",
  "ans": "B",
  "e": "Ulnar nerve compression at elbow is cubital tunnel syndrome; entrapment of the ulnar nerve at the medial epicondyle produces numbness of the 4th and 5th fingers and intrinsic hand muscle weakness.<br><br>Tinel sign at the elbow reproduces symptoms. Froment sign demonstrates adductor pollicis weakness. Nerve conduction studies confirm slowing across the elbow. Treatment includes elbow padding, avoidance of pressure, and surgical decompression in refractory cases or when motor weakness develops clinically.<br><br>Carpal tunnel syndrome (option B) compresses median nerve at wrist; radial tunnel syndrome (option C) compresses radial nerve; thoracic outlet syndrome (option D) compresses brachial plexus, distinct from ulnar at elbow.<br><br><em>(First Aid for USMLE Step 1)</em>"
