  "e": "Multifocal neuropathy commonly presents with mononeuritis multiplex; asymmetric involvement of multiple individual peripheral nerves produces patchy motor and sensory deficits in vasculitic neuropathies.<br><br>Causes include polyarteritis nodosa, Churg-Strauss syndrome, granulomatosis with polyangiitis, diabetic mononeuropathy multiplex, leprosy, and HIV neuropathy. Nerve biopsy may show vasculitis. Treatment addresses underlying cause with immunosuppression for vasculitic causes producing improvement in many patients clinically.<br><br>Symmetric polyneuropathy (option B) is distal-symmetric pattern; radiculopathy (option C) is nerve root involvement; demyelinating neuropathy (option D) is symmetric, distinct from asymmetric multifocal mononeuritis multiplex pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
