  "d": "Acetylcholine receptor",
  "ans": "D",
  "e": "Myasthenia gravis antibodies target acetylcholine receptors; postsynaptic acetylcholine receptors at neuromuscular junction are blocked or downregulated by antibodies producing fatigable weakness.<br><br>Generalised myasthenia features fluctuating weakness affecting ocular (ptosis, diplopia), bulbar (dysphagia, dysarthria), and limb muscles. Repetitive stimulation shows decremental response on EMG. Edrophonium and ice pack tests support diagnosis. Treatment includes pyridostigmine, immunosuppression, and thymectomy.<br><br>Voltage-gated calcium channels (option A) are LEMS targets; sodium channels (option B) are antiepileptic targets; potassium channels (option C) are in autoimmune ataxia, none being the myasthenia AChR target.<br><br><em>(First Aid for USMLE Step 1)</em>"
