  "c": "Improves with activity",
  "d": "Spastic",
  "ans": "B",
  "e": "Edrophonium test in myasthenia gravis shows transient improvement in weakness; this short-acting acetylcholinesterase inhibitor temporarily increases acetylcholine availability improving fatigability briefly.<br><br>Edrophonium (Tensilon) is rarely used now due to availability of more specific testing. Anti-AChR antibody testing has high specificity. Repetitive nerve stimulation shows decremental response. Single fibre EMG is the most sensitive electrophysiological test. Anti-MuSK antibodies are positive in some seronegative cases clinically.<br><br>Worsens weakness (option B) is opposite of expected; produces seizure (option C) is non-specific reaction; causes coma (option D) is severe overdose, none being the edrophonium transient improvement myasthenia gravis test response.<br><br><em>(First Aid for USMLE Step 1)</em>"
