  "d": "Renal failure",
  "ans": "C",
  "e": "Most common ocular feature of myasthenia gravis is ptosis; fluctuating asymmetric ptosis, often worse at the end of the day, is the most common initial manifestation in many patients.<br><br>Diplopia from extraocular muscle weakness is also common. Ocular myasthenia confined to eye muscles for over 2 years rarely generalises. Cogan lid twitch sign and ice pack test support clinical diagnosis. Treatment includes pyridostigmine and immunosuppression in symptomatic patients clinically.<br><br>Anisocoria (option B) is pupil asymmetry; nystagmus (option C) is rhythmic eye movement; visual loss (option D) is from optic nerve disease, none being the myasthenia gravis ptosis fatigable lid drop manifestation principally.<br><br><em>(First Aid for USMLE Step 1)</em>"
