  "e": "Myasthenia gravis EMG shows decremental response on repetitive stimulation; reduction in muscle action potential amplitude after repeated stimulation reflects neuromuscular junction transmission failure.<br><br>Greater than 10 percent decrement on slow repetitive stimulation supports diagnosis. Single fibre EMG is the most sensitive electrophysiological test showing increased jitter. Anti-AChR antibodies have high specificity. Anti-MuSK antibodies are positive in some seronegative cases. Edrophonium and ice pack tests provide bedside support clinically.<br><br>Incremental response (option A) is seen in Lambert-Eaton syndrome; normal response (option C) excludes diagnosis; fasciculations (option D) suggest motor neuron disease, none being the myasthenia decrement.<br><br><em>(First Aid for USMLE Step 1)</em>"
