  "e": "Myasthenia gravis crisis treatment includes plasmapheresis or IVIG; both immunomodulatory therapies provide rapid response in severe exacerbations with respiratory or bulbar involvement.<br><br>Mechanical ventilation supports respiratory failure. Pyridostigmine is sometimes withheld initially to distinguish from cholinergic crisis. Immunosuppression is intensified or continued during crisis recovery. Thymectomy is contraindicated during active crisis. Triggers include infection, surgery, and certain medications requiring identification and avoidance.<br><br>Antibiotics alone (option A) inadequate without immunomodulation; oral steroids only (option B) act slowly; physical therapy (option D) is supportive only, none being principal myasthenia crisis IVIG-plasmapheresis emergency treatment.<br><br><em>(First Aid for USMLE Step 1)</em>"
