  "e": "Lambert-Eaton myasthenic syndrome differs from myasthenia in showing improvement with sustained contraction; brief facilitation of strength after sustained effort is characteristic of LEMS.<br><br>Lambert sign reflects calcium-dependent acetylcholine release facilitation with high-frequency stimulation. Repetitive nerve stimulation shows incremental response in LEMS contrasting with decremental response in myasthenia. Anti-VGCC antibodies are positive. Treatment of underlying small cell lung cancer often improves symptoms alongside 3,4-diaminopyridine and immunosuppression.<br><br>Worsening with exercise (option A) suggests myasthenia; pupillary dilation (option C) is non-specific; tongue fasciculations (option D) suggest motor neuron disease, none being the LEMS Lambert sign sustained contraction improvement.<br><br><em>(First Aid for USMLE Step 1)</em>"
