  "ans": "B",
  "e": "Lambert-Eaton myasthenic syndrome is the likely diagnosis; smoker with proximal muscle weakness improving after effort and dry mouth fits LEMS with autonomic dysfunction and underlying small cell lung cancer.<br><br>Anti-VGCC antibodies confirm diagnosis. Repetitive nerve stimulation shows incremental response. Treatment of underlying small cell lung cancer often improves symptoms. 3,4-diaminopyridine and immunosuppressive therapy provide additional symptomatic benefit. CT chest screens for malignancy in all newly diagnosed LEMS patients.<br><br>Myasthenia gravis (option A) shows decremental response and worsens with effort; multiple sclerosis (option C) features demyelinating CNS plaques; motor neuron disease (option D) shows fasciculations, distinct from LEMS pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
