  "d": "Presynaptic calcium channel blockade",
  "ans": "D",
  "e": "3,4-Diaminopyridine treats Lambert-Eaton myasthenic syndrome; this potassium channel blocker prolongs nerve depolarisation, increasing calcium influx and acetylcholine release at the neuromuscular junction.<br><br>Symptomatic improvement of muscle weakness occurs in most patients. Side effects include paraesthesia, gastrointestinal upset, and rarely seizures at high doses. Treatment of underlying small cell lung cancer often improves symptoms. Immunosuppression with corticosteroids, azathioprine, or rituximab benefits some patients clinically.<br><br>Pyridostigmine (option A) is for myasthenia gravis; donepezil (option C) is for Alzheimer disease; phenytoin (option D) is for epilepsy, none being principal LEMS symptomatic 3,4-diaminopyridine treatment.<br><br><em>(First Aid for USMLE Step 1)</em>"
