  "e": "Treatment of botulism is botulinum antitoxin and supportive care; equine antitoxin neutralises circulating toxin while mechanical ventilation supports respiratory failure during recovery.<br><br>Antitoxin should be given as early as possible after diagnosis. Wound debridement and antibiotics treat wound botulism. Infant botulism is treated with human botulism immune globulin (BabyBIG). Recovery may take weeks to months as new neuromuscular junctions form following toxin-mediated SNARE cleavage clinically.<br><br>Pyridostigmine alone (option A) does not neutralise toxin; surgery alone (option C) inadequate; physical therapy alone (option D) is supportive, none being principal botulism antitoxin and supportive care emergency treatment.<br><br><em>(First Aid for USMLE Step 1)</em>"
