  "e": "Botulism differs from MG because pupils are dilated and unreactive in botulism; autonomic dysfunction from cholinergic blockade produces fixed dilated pupils, dry mouth, ileus, and urinary retention.<br><br>Myasthenia gravis spares pupils because autonomic ganglia have nicotinic receptors. Both conditions produce muscle weakness with respiratory failure but autonomic features distinguish them. Botulism causes descending paralysis while myasthenia is fluctuating and fatigable. Treatment differs accordingly.<br><br>Pupils constricted (option A) is opposite of botulism finding; pupils normal (option B) characterises myasthenia gravis; nystagmus (option D) is non-specific, none being the botulism dilated unreactive pupil autonomic feature.<br><br><em>(First Aid for USMLE Step 1)</em>"
