  "e": "Tetanus is caused by Clostridium tetani; this Gram-positive anaerobic spore-forming bacillus produces tetanospasmin which inhibits glycine and GABA release at inhibitory interneurons producing severe muscle spasms.<br><br>Clinical features include trismus (lockjaw), risus sardonicus, opisthotonos, and autonomic instability. Treatment includes wound debridement, human tetanus immune globulin, antibiotics (metronidazole), supportive care, and active immunisation. Vaccination prevents infection effectively in immunised populations.<br><br>Clostridium botulinum (option A) causes botulism; Clostridium difficile (option C) causes colitis; Clostridium perfringens (option D) causes gas gangrene, none being the tetanospasmin-producing tetanus organism.<br><br><em>(First Aid for USMLE Step 1)</em>"
