  "e": "Treatment of tetanus includes tetanus immunoglobulin and metronidazole; passive immunisation neutralises circulating toxin while metronidazole eradicates Clostridium tetani from the wound.<br><br>Wound debridement removes the bacterial source. Supportive care includes airway management, sedation with benzodiazepines for spasms, autonomic dysfunction management, and active immunisation. Recovery may take weeks. Mortality remains substantial in severe disease without ICU support clinically.<br><br>Penicillin alone (option B) is alternative antibiotic but does not neutralise toxin; oral steroids (option C) are not effective; antiviral therapy (option D) is irrelevant, none being principal tetanus comprehensive treatment.<br><br><em>(First Aid for USMLE Step 1)</em>"
