  "e": "Brachial plexus injury at upper trunk is Erb-Duchenne palsy; injury to C5 and C6 nerve roots produces waiter's tip posture (arm adducted, elbow extended, forearm pronated, wrist flexed).<br><br>Causes include shoulder dystocia at birth, motorcycle accidents, and trauma. Most birth-related cases recover spontaneously. Persistent deficits may benefit from physical therapy and surgical reconstruction. Lower trunk injuries (Klumpke palsy) affect C8-T1 roots producing claw hand and Horner syndrome clinically.<br><br>Klumpke palsy (option B) is C8-T1; long thoracic nerve palsy (option C) causes winged scapula; suprascapular nerve (option D) supplies supraspinatus and infraspinatus, distinct from upper trunk Erb-Duchenne palsy.<br><br><em>(First Aid for USMLE Step 1)</em>"
