  "e": "Most common acquired peripheral neuropathy is diabetic neuropathy; diabetes mellitus is the most common cause of peripheral neuropathy globally, particularly in developed countries with diabetes prevalence.<br><br>Distal symmetric polyneuropathy is the most common form. Strict glycaemic control reduces progression. Treatment includes pregabalin, gabapentin, duloxetine, and amitriptyline for neuropathic pain. Foot care education prevents ulceration. Other diabetic neuropathies include autonomic, mononeuropathy, and amyotrophy in some patients.<br><br>Charcot-Marie-Tooth disease (option B) is hereditary; vasculitic neuropathy (option C) features mononeuritis multiplex; HIV neuropathy (option D) is opportunistic, none surpassing diabetic frequency in acquired peripheral neuropathy globally.<br><br><em>(First Aid for USMLE Step 1)</em>"
