  "e": "Investigation of choice for neuromuscular junction disorders is repetitive nerve stimulation; this electrophysiological test demonstrates decremental response in myasthenia gravis and incremental response in Lambert-Eaton syndrome.<br><br>Single fibre EMG is the most sensitive test for myasthenia gravis showing increased jitter. Anti-AChR antibodies have high specificity. Anti-MuSK antibodies are positive in some seronegative cases. Anti-VGCC antibodies confirm Lambert-Eaton syndrome. CT chest evaluates thymus and lung clinically.<br><br>CT brain (option A) is for cerebral imaging; lumbar puncture (option B) is for CNS infection or demyelination; muscle biopsy (option D) is for myopathy, none being neuromuscular junction repetitive nerve stimulation.<br><br><em>(First Aid for USMLE Step 1)</em>"
