  "e": "Drug commonly causing peripheral neuropathy is isoniazid; this antitubercular drug interferes with pyridoxine metabolism producing peripheral neuropathy preventable by pyridoxine supplementation.<br><br>Other neurotoxic drugs include vincristine (chemotherapy), platinum agents (cisplatin), taxanes, amiodarone, metronidazole, nitrofurantoin, and statins. Drug history is essential in evaluating peripheral neuropathy. Discontinuation when feasible and supplementation of relevant cofactors (pyridoxine for isoniazid) facilitates recovery clinically.<br><br>Aspirin (option A), insulin (option B), and metformin (option C) are not principal neurotoxic drugs, leaving isoniazid (and other recognised neurotoxic chemotherapy and antimicrobial agents) as established drug-induced neuropathy aetiology.<br><br><em>(First Aid for USMLE Step 1)</em>"
