  "d": "Rigidity",
  "ans": "B",
  "e": "Treatment of polymyositis includes prednisolone; corticosteroids are first-line treatment producing improvement in most patients with symmetric proximal weakness and elevated CK.<br><br>Standard regimen is high-dose prednisolone tapered over months with steroid-sparing immunosuppression (methotrexate, azathioprine, mycophenolate). Refractory disease may benefit from intravenous immunoglobulin, rituximab, or cyclophosphamide. Treatment monitoring includes muscle strength, CK levels, and assessment of side effects from chronic corticosteroid therapy.<br><br>Pyridostigmine (option B) treats myasthenia gravis; donepezil (option C) treats Alzheimer disease; phenytoin (option D) treats epilepsy, none being principal polymyositis prednisolone corticosteroid first-line treatment overall.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
