  "e": "Cushingoid features in patient on prednisolone include moon facies and buffalo hump; chronic corticosteroid therapy produces these characteristic redistributive obesity features alongside other Cushing syndrome features.<br><br>Other features include central obesity, thin extremities, abdominal striae, hypertension, hyperglycaemia, osteoporosis, and proximal myopathy. Steroid-sparing immunosuppression and gradual taper to lowest effective dose minimise long-term complications. Bone density monitoring and prophylaxis with calcium, vitamin D, and bisphosphonates address osteoporosis risk.<br><br>Hypoglycaemia (option B), hypotension (option C), and weight loss (option D) are opposite of Cushingoid features, leaving moon facies and buffalo hump as principal corticosteroid Cushingoid manifestations clinically observed.<br><br><em>(First Aid for USMLE Step 1)</em>"
