  "e": "Inclusion body myositis differs from polymyositis by older age and asymmetric distal involvement; this most common acquired myopathy in elderly features asymmetric weakness with finger flexor and quadriceps predominance.<br><br>Rimmed vacuoles and inclusion bodies on muscle biopsy. Anti-cN1A antibodies are specific. Disease is refractory to immunosuppression unlike polymyositis. Treatment with corticosteroids, methotrexate, intravenous immunoglobulin produces limited benefit. Disease progresses slowly over years requiring physical therapy and assistive devices clinically.<br><br>More rapid onset (option A) suggests polymyositis; better steroid response (option B) is opposite of IBM; symmetric proximal only (option D) is polymyositis pattern, distinct from IBM asymmetric distal pattern in elderly.<br><br><em>(First Aid for USMLE Step 1)</em>"
