  "e": "Most common cause of acute rhabdomyolysis is trauma or crush injury; muscle damage from trauma releases myoglobin causing acute kidney injury through tubular obstruction and direct nephrotoxicity.<br><br>Other causes include strenuous exercise, prolonged immobilisation, drug toxicity (statins, alcohol, cocaine), seizures, electrolyte abnormalities, and metabolic myopathies. CK elevation over 5 times upper limit, myoglobinuria, and acute kidney injury characterise diagnosis. Aggressive intravenous fluid resuscitation prevents renal failure clinically.<br><br>Genetic disease (option A) is uncommon acute trigger; viral infection (option B) is rare; chronic kidney disease (option D) is consequence not cause, none being principal trauma-rhabdomyolysis acute aetiology overall.<br><br><em>(First Aid for USMLE Step 1)</em>"
