  "ans": "A",
  "e": "Steroid myopathy is painless proximal weakness; chronic corticosteroid use produces type II muscle fibre atrophy with normal CK and minimal inflammatory features distinguishing from inflammatory myopathy.<br><br>Onset typically after months of high-dose corticosteroid therapy. Reduction or discontinuation of corticosteroid produces gradual improvement. Differential diagnosis from polymyositis or dermatomyositis recurrence is challenging in patients on corticosteroid treatment for inflammatory myopathy. Steroid-sparing immunosuppression may help in chronic care.<br><br>Painful weakness (option A) suggests inflammation; distal weakness (option C) is uncommon; sensory loss (option D) suggests neuropathy, distinct from painless proximal steroid myopathy pattern observed in patients clinically.<br><br><em>(First Aid for USMLE Step 1)</em>"
