  "b": "Tumor cells",
  "c": "Plaques",
  "d": "Perimysial inflammation",
  "ans": "D",
  "e": "Adult muscular dystrophy commonly presenting with myotonia and cataracts is myotonic dystrophy; the multisystem features of myotonia, distal weakness, frontal balding, cataracts, cardiac conduction, diabetes characterise it.<br><br>CTG trinucleotide repeat expansion in DMPK gene produces autosomal dominant disease. Anticipation occurs with maternal transmission. Treatment is supportive with mexiletine for myotonia, pacemaker for conduction disease, ophthalmologic management of cataracts, and orthopaedic management. Multisystem clinical care addresses respiratory, endocrine, and cardiac complications.<br><br>Becker muscular dystrophy (option A) is X-linked recessive without cataracts; limb-girdle muscular dystrophy (option C) is heterogeneous group; facioscapulohumeral dystrophy (option D) features facial-shoulder weakness, distinct from myotonic dystrophy multisystem features.<br><br><em>(First Aid for USMLE Step 1)</em>"
