  "c": "Metabolic myopathy",
  "d": "ALS",
  "ans": "C",
  "e": "Carrier of Duchenne muscular dystrophy may show mild cardiomyopathy; female carriers may develop variable cardiac involvement from non-random X-inactivation despite usually being asymptomatic for skeletal muscle disease.<br><br>Genetic counselling addresses inheritance for family. Cardiac screening with echocardiography and ECG identifies carriers with cardiomyopathy needing treatment with ACE inhibitors and beta-blockers. Some carriers have mild proximal weakness with elevated CK warranting monitoring and supportive care depending on severity clinically.<br><br>Severe ataxia (option A) is not characteristic; pure cognitive deficit (option C) is uncommon; sensory loss (option D) does not occur, none being the carrier mild cardiomyopathy DMD female carrier potential clinical feature.<br><br><em>(First Aid for USMLE Step 1)</em>"
