  "e": "Cervical radiculopathy is the diagnosis; neck pain radiating to arm with thumb paraesthesia and reduced biceps reflex localises to C6 nerve root compression typically.<br><br>C6 radiculopathy produces sensory loss in thumb and lateral forearm, weakness of biceps and wrist extensors, reduced biceps and brachioradialis reflexes. Cervical disc herniation, spondylotic foraminal narrowing, and tumour are common causes. MRI characterises lesion. Conservative management or surgical decompression treats persistent disease.<br><br>Cervical myelopathy (option B) features bilateral signs and gait ataxia; brachial plexopathy (option C) involves multiple roots; carpal tunnel syndrome (option D) is distal entrapment, distinct from C6 radiculopathy.<br><br><em>(First Aid for USMLE Step 1)</em>"
