  "e": "Cauda equina syndrome features bilateral lower limb weakness with saddle anaesthesia and bladder dysfunction; lumbosacral nerve root compression below conus produces lower motor neuron signs.<br><br>Causes include large central disc herniation, tumour, abscess, and trauma. Surgical decompression within 48 hours preserves function. Delayed treatment produces permanent sphincter and sexual dysfunction. Urinary retention with overflow incontinence is the classic finding requiring urgent imaging and neurosurgical evaluation immediately.<br><br>Conus medullaris syndrome (option A) features mixed UMN-LMN signs; cervical myelopathy (option C) is in upper limbs; lumbar spondylosis (option D) produces radiculopathy without sphincter involvement, distinct from cauda equina.<br><br><em>(First Aid for USMLE Step 1)</em>"
