  "e": "Acute transverse myelitis presents with rapid sensory level and weakness; bilateral lower limb weakness with sensory level on torso developing over hours to days suggests transverse myelitis.<br><br>Causes include multiple sclerosis, neuromyelitis optica, infections, post-vaccination, and idiopathic. MRI shows cord oedema and contrast enhancement. CSF shows pleocytosis and elevated protein. Treatment with high-dose corticosteroids and plasmapheresis. Aetiology determines long-term management and recurrence prevention strategies clinically.<br><br>Carpal tunnel (option B) is wrist entrapment; cervical radiculopathy (option C) is unilateral; cauda equina (option D) is below conus, distinct from acute transverse myelitis bilateral cord pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
