  "e": "Anterior cord syndrome features motor and pain-temperature loss; anterior spinal artery occlusion or compression spares dorsal columns producing bilateral motor and spinothalamic loss with preserved vibration and proprioception.<br><br>Causes include atherosclerosis, dissecting aortic aneurysm, hypotension during cross-clamping, and trauma. MRI shows anterior cord infarct. Treatment is supportive with physical therapy. Recovery is variable depending on duration and extent of ischaemia. Prevention focuses on cardiovascular risk factor management in vulnerable patients clinically.<br><br>Posterior cord syndrome (option B) is opposite pattern; central cord syndrome (option C) is upper limb predominant; Brown-Sequard syndrome (option D) is hemicord, distinct from anterior cord motor-spinothalamic pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
