  "e": "Conus medullaris syndrome features mixed upper and lower motor neuron signs; lesion at the conus produces lower limb weakness, saddle anaesthesia, sphincter dysfunction with hyperreflexia and Babinski sign.<br><br>Causes include disc herniation, tumour, trauma, and infection. MRI characterises lesion. Treatment includes urgent surgical decompression, high-dose corticosteroids, and disease-specific management. Distinction from pure cauda equina syndrome (lower motor neuron only) is important for prognosis and surgical approach in clinical practice.<br><br>Pure UMN signs (option A) suggest cervical/thoracic cord; pure LMN signs (option B) suggest cauda equina; sensory only (option D) is unusual, none matching conus mixed pattern with sphincter dysfunction.<br><br><em>(First Aid for USMLE Step 1)</em>"
