  "e": "Most common cause of spinal cord compression in adults is vertebral metastasis; tumour involvement of vertebral body with epidural extension compresses cord producing back pain followed by myelopathy.<br><br>Common primary tumours include breast, lung, prostate, kidney, and lymphoma. Treatment includes high-dose dexamethasone, urgent imaging, and surgical decompression or radiotherapy depending on tumour radiosensitivity. Bisphosphonates and denosumab reduce skeletal-related events. Outcome depends on duration and degree of cord compression at presentation.<br><br>Disc herniation (option A) is acute focal cause; trauma (option B) is acute; tuberculosis (option D) is less common, none surpassing metastatic vertebral involvement as principal spinal cord compression aetiology in adults.<br><br><em>(First Aid for USMLE Step 1)</em>"
