  "e": "Spinal cord injury complete level above C5 leads to respiratory failure; involvement of phrenic nerve nuclei (C3-C5) impairs diaphragmatic function requiring mechanical ventilation in high cervical injury.<br><br>C5 and below preserves diaphragmatic function but loses intercostal muscle function. Spinal shock with flaccid paralysis and areflexia immediately follows injury, evolving over weeks to spasticity. Treatment in spinal injury units improves outcomes through prevention of secondary complications including pressure ulcers, contractures, and autonomic dysreflexia.<br><br>C7 (option B), T1 (option C), and L1 (option D) injuries spare diaphragmatic function, leaving high cervical (above C5) injuries as the principal spinal cord level requiring mechanical ventilation.<br><br><em>(First Aid for USMLE Step 1)</em>"
