  "e": "Horner syndrome triad is ptosis, miosis, and anhidrosis; ipsilateral sympathetic interruption produces these three classical features alongside variable apparent enophthalmos.<br><br>Causes include Pancoast tumour, carotid dissection, lateral medullary syndrome, brachial plexus injury, and orbital lesions. Pharmacological testing (cocaine, hydroxyamphetamine) localises lesion level. Imaging characterises underlying cause. Treatment addresses underlying lesion. Cosmetic ptosis correction may be considered for chronic disease in clinical practice for affected patients.<br><br>Mydriasis (option B) is opposite of Horner finding; ophthalmoplegia (option C) is from CN III; proptosis (option D) is opposite of Horner enophthalmos, distinct from Horner ptosis-miosis-anhidrosis sympathetic triad.<br><br><em>(First Aid for USMLE Step 1)</em>"
