  "d": "Corticospinal tract",
  "ans": "D",
  "e": "Lateral medullary (Wallenberg) syndrome is the diagnosis; sudden vertigo with ipsilateral facial pain loss and contralateral body pain loss from posterior inferior cerebellar artery occlusion.<br><br>Other features include ipsilateral Horner syndrome, dysphagia, dysarthria, ataxia, and nystagmus. Vestibular nuclei, descending trigeminal tract, ascending spinothalamic tract, and inferior cerebellar peduncle involvement produces clinical syndrome. Treatment includes acute stroke management with antiplatelet therapy, statin, and risk factor modification. Vertebral artery dissection is common cause clinically.<br><br>Medial medullary syndrome (option A) features pyramidal signs and tongue weakness; lateral pontine syndrome (option B) is in pons; cerebellar infarct (option C) produces ataxia without crossed sensory pattern, distinct from Wallenberg.<br><br><em>(First Aid for USMLE Step 1)</em>"
