  "e": "Internuclear ophthalmoplegia is from medial longitudinal fasciculus lesion; failure of adduction of ipsilateral eye with nystagmus of contralateral abducting eye localises to the MLF.<br><br>Bilateral INO in young patient strongly suggests multiple sclerosis. Unilateral INO in elderly suggests brainstem ischaemia. MRI characterises lesion. Treatment addresses underlying cause: corticosteroids and disease-modifying therapy for MS, antiplatelet therapy for stroke. Recovery is variable depending on aetiology and extent of damage in clinical practice.<br><br>Cerebellar lesion (option B) produces ataxia and dysmetria; cortical lesion (option C) produces hemiparesis; spinal cord lesion (option D) produces weakness, distinct from MLF internuclear ophthalmoplegia eye movement pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
