  "d": "Basal ganglia",
  "ans": "D",
  "e": "Resting tremor disappearing during sleep originates from basal ganglia; Parkinson disease pill-rolling resting tremor at 4-6 Hz frequency improves with action and disappears in sleep, reflecting basal ganglia dysfunction.<br><br>Loss of dopaminergic neurons in substantia nigra pars compacta with Lewy bodies underlies pathology. Tremor is asymmetric at onset, often beginning in one upper limb. Re-emergent postural tremor may also occur. Levodopa-carbidopa is the most effective treatment. Other options include dopamine agonists, MAO-B inhibitors clinically.<br><br>Cerebellar lesion (option A) produces intention tremor; cortical lesion (option B) produces hemiparesis; peripheral nerve lesion (option C) produces neuropathy, distinct from basal ganglia resting tremor of Parkinson.<br><br><em>(First Aid for USMLE Step 1)</em>"
