  "ans": "B",
  "e": "Most common type of focal seizure is temporal lobe seizure; mesial temporal lobe origin produces focal seizures with characteristic auras and semiology.<br><br>Auras include rising epigastric sensation, fear, deja vu, jamais vu, and unpleasant smell. Seizures may include automatisms (lip smacking, hand fumbling) with impaired awareness. EEG shows temporal lobe spikes. MRI may show hippocampal sclerosis. Anti-epileptic drugs and epilepsy surgery (anterior temporal lobectomy) are treatment options for focal epilepsy clinically.<br><br>Frontal lobe seizures (option B) are nocturnal and motor; parietal lobe seizures (option C) are sensory; occipital lobe seizures (option D) are visual, none surpassing temporal lobe focal seizure frequency.<br><br><em>(First Aid for USMLE Step 1)</em>"
