  "e": "Most common adverse effect of phenytoin is gingival hyperplasia; chronic phenytoin use produces gum overgrowth alongside hirsutism, coarsening of facial features, and acne.<br><br>Other adverse effects include dose-dependent neurotoxicity (nystagmus, ataxia, dysarthria), hepatotoxicity, megaloblastic anaemia (folate antagonism), Stevens-Johnson syndrome, peripheral neuropathy, and osteomalacia. Therapeutic drug monitoring guides dosing. Newer anti-epileptic drugs (levetiracetam, lamotrigine) have better tolerability profiles clinically.<br><br>Hyperthyroidism (option A) is unrelated; aplastic anaemia (option B) is rare; weight loss (option D) is unusual, none being the principal phenytoin gingival hyperplasia chronic adverse effect.<br><br><em>(First Aid for USMLE Step 1)</em>"
