  "d": "IV lorazepam",
  "ans": "D",
  "e": "Most appropriate first-line drug for tonic-clonic seizures is sodium valproate; this broad-spectrum anti-epileptic drug is first-line for primary generalised epilepsy with tonic-clonic, absence, and myoclonic seizures.<br><br>Mechanism involves GABA potentiation and sodium channel modulation. Side effects include weight gain, hair loss, tremor, hepatotoxicity, pancreatitis, and teratogenicity (neural tube defects). Avoid in women of childbearing age unless other options fail. Levetiracetam and lamotrigine are alternatives in pregnancy planning clinically.<br><br>Carbamazepine (option B) may worsen absence seizures; ethosuximide (option C) is for absence only; gabapentin (option D) is for focal seizures, none being principal first-line tonic-clonic seizure treatment.<br><br><em>(First Aid for USMLE Step 1)</em>"
