  "ans": "A",
  "e": "Todd paralysis occurs after generalised tonic-clonic or focal motor seizure; transient post-ictal weakness lasting hours to days reflects post-seizure neuronal dysfunction in motor pathway.<br><br>Recovery is complete in most cases. Distinguishing Todd paralysis from stroke is important to avoid inappropriate thrombolysis. Imaging may be required if uncertainty exists. Other post-ictal phenomena include aphasia, sensory disturbance, and confusion. Recognition of Todd paralysis pattern prevents unnecessary investigation in patients with known epilepsy clinically.<br><br>Migraine (option B) is headache disorder; multiple sclerosis (option C) is CNS demyelinating; concussion (option D) is from head trauma, distinct from Todd post-ictal transient paralysis after seizure.<br><br><em>(First Aid for USMLE Step 1)</em>"
