  "d": "Absence seizure",
  "ans": "B",
  "e": "Most common cause of status epilepticus in known epileptic is medication non-adherence; missed anti-epileptic drug doses are the principal cause of breakthrough seizures progressing to status.<br><br>Other causes include drug interactions, intercurrent illness, sleep deprivation, alcohol, and progression of underlying neurological disease. Treatment of status epilepticus follows stepwise protocol: benzodiazepines (lorazepam, midazolam) first, then anti-epileptic drug (levetiracetam, valproate, fosphenytoin), then anaesthetic agents (propofol, midazolam infusion) for refractory status clinically.<br><br>New brain tumour (option B) is uncommon; metabolic encephalopathy (option C) is uncommon precipitant; CNS infection (option D) is uncommon, none surpassing medication non-adherence as principal known-epileptic status precipitant.<br><br><em>(First Aid for USMLE Step 1)</em>"
