  "e": "Most common cause of intracerebral haemorrhage is hypertension; chronic hypertension damages small perforating arteries producing Charcot-Bouchard microaneurysms with rupture causing intracerebral haemorrhage.<br><br>Common haemorrhage locations include putamen, thalamus, pons, and cerebellum. Treatment includes blood pressure control, neurocritical care, and surgical evacuation in selected cases. Other causes include cerebral amyloid angiopathy (lobar haemorrhage in elderly), arteriovenous malformation, tumour, anticoagulation, and trauma. Long-term prevention requires aggressive hypertension management clinically.<br><br>Aneurysm (option A) typically causes subarachnoid haemorrhage; trauma (option C) is distinct mechanism; arteriovenous malformation (option D) is less common, none surpassing hypertension as principal intracerebral haemorrhage cause.<br><br><em>(First Aid for USMLE Step 1)</em>"
