  "e": "Lacunar stroke produces pure motor hemiparesis from internal capsule infarct; small vessel disease from hypertension and diabetes produces this characteristic pure motor lacunar syndrome.<br><br>Other classic lacunar syndromes include pure sensory stroke (thalamic), sensorimotor stroke, ataxic hemiparesis, and dysarthria-clumsy hand syndrome. MRI is more sensitive than CT for detection. Treatment includes acute stroke management with antiplatelet therapy, statin, and risk factor modification. Long-term prevention requires aggressive vascular risk factor management clinically.<br><br>Cortical infarct (option A) typically produces hemiparesis with cortical features; cerebellar infarct (option B) produces ataxia; brainstem infarct (option D) produces crossed signs, distinct from lacunar internal capsule pure motor.<br><br><em>(First Aid for USMLE Step 1)</em>"
