  "c": "EEG",
  "d": "CT scan",
  "ans": "B",
  "e": "Most common cause of basilar artery thrombosis is atherosclerosis; vertebrobasilar atherosclerosis produces basilar thrombosis with brainstem and cerebellar infarction.<br><br>Common features include altered consciousness, cranial nerve palsies, motor deficits, and ataxia. Locked-in syndrome may develop from bilateral ventral pontine infarction. Treatment includes acute stroke management with thrombolysis or thrombectomy in eligible patients. Mortality remains substantial in untreated basilar thrombosis. Long-term prevention requires aggressive vascular risk factor management clinically.<br><br>Cardioembolic (option B) and arterial dissection (option C) cause some cases but less common than atherosclerosis; vasculitis (option D) is rare cause, none surpassing atherosclerosis as principal basilar thrombosis aetiology.<br><br><em>(First Aid for USMLE Step 1)</em>"
