  "e": "Most common cause of ataxia in alcoholic is cerebellar degeneration; chronic alcohol abuse produces selective vermis atrophy with truncate ataxia and gait instability.<br><br>Alcohol-related cerebellar degeneration affects predominantly anterior superior vermis. Patients present with broad-based gait, truncate ataxia, and limb ataxia. Thiamine deficiency may coexist requiring supplementation. Abstinence prevents further progression but established deficits are typically irreversible. Treatment is supportive with physical therapy and rehabilitation in clinical practice.<br><br>Wernicke encephalopathy (option B) is acute thiamine deficiency; multiple sclerosis (option C) is CNS demyelinating; cerebrovascular accident (option D) is acute, distinct from chronic alcoholic cerebellar degeneration.<br><br><em>(First Aid for USMLE Step 1)</em>"
