  "e": "Most common cause of cerebellar stroke is vertebrobasilar atherosclerosis; vertebrobasilar atherosclerosis produces cerebellar infarction with ataxia, vertigo, and headache as initial features.<br><br>Common syndromes include posterior inferior cerebellar artery (PICA) syndrome producing lateral medullary syndrome and superior cerebellar artery (SCA) syndrome. Treatment includes acute stroke management with thrombolysis or thrombectomy in eligible patients. Posterior fossa decompression may be required for malignant cerebellar oedema with brainstem compression clinically.<br><br>Cardioembolic (option B) is less common; arterial dissection (option C) is less common; vasculitis (option D) is rare, none surpassing atherosclerosis as principal cerebellar stroke cause.<br><br><em>(First Aid for USMLE Step 1)</em>"
