  "e": "Most common type of intracranial haemorrhage is intracerebral; hypertensive intracerebral haemorrhage is the most common spontaneous intracranial haemorrhage globally.<br><br>Common haemorrhage locations include putamen, thalamus, pons, and cerebellum. Treatment includes blood pressure control, neurocritical care, and surgical evacuation in selected cases. Other causes include cerebral amyloid angiopathy (lobar haemorrhage in elderly), arteriovenous malformation, tumour, anticoagulation, and trauma. Long-term prevention requires aggressive hypertension management in patients clinically.<br><br>Subarachnoid (option A) is less common; subdural (option C) is traumatic; epidural (option D) is traumatic, none surpassing intracerebral haemorrhage as principal spontaneous intracranial haemorrhage type.<br><br><em>(First Aid for USMLE Step 1)</em>"
