  "e": "Most common location of hypertensive intracerebral haemorrhage is putamen; this deep grey matter structure is supplied by lenticulostriate arteries vulnerable to chronic hypertensive vasculopathy.<br><br>Other typical hypertensive locations include thalamus, pons, and cerebellum. Lobar haemorrhage in elderly suggests cerebral amyloid angiopathy. Imaging characteristics and patient age guide differential diagnosis between hypertensive and amyloid haemorrhage clinically. Treatment includes blood pressure control, neurocritical care, and surgical evacuation in selected cases.<br><br>Cortex (option B) suggests amyloid angiopathy; subarachnoid (option C) is aneurysmal; subdural (option D) is traumatic, distinct from putamen as principal hypertensive intracerebral haemorrhage location.<br><br><em>(First Aid for USMLE Step 1)</em>"
