  "e": "Cerebellar lesion features intention tremor, dysmetria, and hypotonia; ipsilateral cerebellar dysfunction produces these characteristic features through impaired motor control.<br><br>Other cerebellar features include dysdiadochokinesia, ataxia, scanning speech, and nystagmus. Anterior lobe cerebellar disease produces predominantly limb ataxia; flocculonodular lobe disease produces vestibular and oculomotor signs; vermis disease produces truncate ataxia. Causes include stroke, multiple sclerosis, alcohol, tumour, and inherited ataxias clinically requiring evaluation.<br><br>Cortex (option A) produces hemiparesis; thalamus (option B) produces sensory loss; basal ganglia (option C) produces movement disorders, distinct from cerebellar intention tremor-dysmetria-hypotonia pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
