  "e": "Most common cause of cerebellar ataxia in young adult is multiple sclerosis; demyelinating plaques in cerebellar pathways produce cerebellar ataxia in young MS patients.<br><br>McDonald criteria require dissemination in space and time. CSF shows oligoclonal bands. MRI demonstrates demyelinating plaques. Treatment includes acute corticosteroids and disease-modifying therapy. Cerebellar involvement may produce intention tremor, dysmetria, ataxia, and dysarthria. Treatment with disease-modifying therapy reduces relapses and slows progression clinically.<br><br>Alcoholic (option B) is in older patients; cerebrovascular accident (option C) is uncommon in young; tumour (option D) is uncommon, none surpassing MS as principal cerebellar ataxia cause in young adults.<br><br><em>(First Aid for USMLE Step 1)</em>"
