  "e": "Malignant hyperthermia is the cause; young athlete collapsing with hyperthermia and muscle rigidity after anaesthesia fits MH from RYR1 gene mutation susceptibility triggered by volatile anaesthetics.<br><br>Volatile anaesthetics (halothane, isoflurane, sevoflurane) and depolarising muscle relaxant succinylcholine trigger malignant hyperthermia. Treatment with dantrolene reverses the hypermetabolic crisis. Pre-anaesthetic precautions including total intravenous anaesthesia avoid triggers. Family screening identifies at-risk relatives for similar precautions clinically.<br><br>Heat stroke (option A) lacks rigidity from anaesthesia; serotonin syndrome (option C) features autonomic features and clonus; neuroleptic malignant syndrome (option D) is from antipsychotics, distinct from anaesthetic-triggered malignant hyperthermia.<br><br><em>(First Aid for USMLE Step 1)</em>"
