  "e": "Treatment of malignant hyperthermia is dantrolene; this skeletal muscle relaxant inhibits calcium release from sarcoplasmic reticulum reversing the hypermetabolic crisis triggered by anaesthetic exposure.<br><br>Standard dosing is 2.5 mg/kg intravenously, repeated as needed up to total of 10 mg/kg. Discontinuation of triggering anaesthetic, cooling, treatment of acidosis and hyperkalaemia, and supportive care. Recovery is generally complete with prompt treatment. Family screening identifies at-risk relatives for pre-anaesthetic precautions clinically in subsequent procedures.<br><br>Antibiotics (option B) treat infection; corticosteroids (option C) are not effective; chemotherapy (option D) is irrelevant, none being principal malignant hyperthermia dantrolene treatment for hypermetabolic crisis.<br><br><em>(First Aid for USMLE Step 1)</em>"
