  "e": "Neuroleptic malignant syndrome features hyperthermia, muscle rigidity, and altered mental state; this idiosyncratic reaction to antipsychotic drugs (typical and atypical) produces life-threatening hypermetabolic state.<br><br>Treatment includes immediate discontinuation of antipsychotic, supportive care with cooling and hydration, dantrolene for severe muscle rigidity, and bromocriptine or amantadine. Recognition of triggers (haloperidol, fluphenazine, atypical antipsychotics) prevents recurrence. Differential diagnosis includes serotonin syndrome and malignant hyperthermia requiring specific evaluation in clinical practice.<br><br>Cluster headache (option A) is autonomic cephalalgia; migraine (option B) is throbbing headache; tension headache (option C) is bilateral pressing, distinct from neuroleptic malignant syndrome hypermetabolic state.<br><br><em>(First Aid for USMLE Step 1)</em>"
